function cleanGithubUrl(value) {
  let url = String(value || '').trim();
  const markdownMatch = url.match(/\((https?:\/\/github\.com\/[^)]+)\)/i);
  if (markdownMatch) url = markdownMatch[1];
  url = url.replace(/^<|>$/g, '').trim();
  if (url.startsWith('//github.com/')) url = 'https:' + url;
  if (/^github\.com\//i.test(url)) url = 'https://' + url;
  url = url.replace(/^https:\/github\.com\//i, 'https://github.com/');
  url = url.replace(/^http:\/github\.com\//i, 'http://github.com/');
  try { return decodeURI(url); } catch { return url; }
}

function parseGithubProductUrl(value) {
  const cleaned = cleanGithubUrl(value);
  if (!cleaned) return null;

  let owner;
  let repo;
  let branch;
  let productTail;

  const treeMatch = cleaned.match(/(?:https?:)?\/\/github\.com\/([^\/\s]+)\/([^\/\s]+)\/tree\/(.+)$/i)
    || cleaned.match(/github\.com\/([^\/\s]+)\/([^\/\s]+)\/tree\/(.+)$/i);
  if (treeMatch) {
    owner = treeMatch[1];
    repo = treeMatch[2];
    const rest = treeMatch[3].replace(/^\/+|\/+$/g, '');
    const marker = '/products/';
    const markerIndex = rest.indexOf(marker);
    if (markerIndex < 1) {
      throw new Error(`github_url must include /tree/{branch}/products/{product_id}. Received: ${cleaned}`);
    }
    branch = rest.slice(0, markerIndex);
    productTail = rest.slice(markerIndex + marker.length);
  } else {
    const titleMatch = cleaned.match(/([^\/\s]+)\/products\/([^\s]+)(?:\s+at\s+([^\s]+))?.*?[·\-]\s*([^\/\s]+)\/([^\/\s]+)/i);
    if (titleMatch) {
      repo = titleMatch[1];
      productTail = titleMatch[2];
      branch = titleMatch[3] || 'main';
      owner = titleMatch[4];
      repo = titleMatch[5] || repo;
    } else {
      const shortMatch = cleaned.match(/([^\/\s]+)\/([^\/\s]+)\/products\/([^\s]+)/i);
      if (shortMatch) {
        owner = shortMatch[1];
        repo = shortMatch[2];
        branch = 'main';
        productTail = shortMatch[3];
      }
    }
  }

  if (!owner || !repo || !branch || !productTail) {
    throw new Error(`github_url must look like https://github.com/{owner}/{repo}/tree/{branch}/products/{product_id}. Received: ${cleaned}`);
  }

  productTail = productTail.replace(/^\/+|\/+$/g, '');
  if (!productTail) {
    throw new Error(`github_url must include product_id. Received: ${cleaned}`);
  }

  return {
    github_url: `https://github.com/${owner}/${repo}/tree/${branch}/products/${productTail}`,
    owner,
    repo,
    branch,
    product_folder: `products/${productTail}`
  };
}
