const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

function normalizePath(value) {
  return String(value || '').replace(/\\/g, '/').replace(/\/+$/, '');
}

async function runPython(pythonExecutable, args, childEnv, timeoutMs) {
  return await new Promise((resolve, reject) => {
    const child = spawn(pythonExecutable, args, {
      windowsHide: true,
      shell: false,
      env: childEnv
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', data => {
      stdout += data.toString();
      if (stdout.length > 1024 * 1024) stdout = stdout.slice(-1024 * 1024);
    });

    child.stderr.on('data', data => {
      stderr += data.toString();
      if (stderr.length > 1024 * 1024) stderr = stderr.slice(-1024 * 1024);
    });

    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch (error) {}
      reject(new Error(`OpenAI Python process timed out after ${timeoutMs}ms. stderr=${stderr.slice(-2000)}`));
    }, timeoutMs);

    child.on('error', error => {
      clearTimeout(timer);
      reject(error);
    });

    child.on('close', code => {
      clearTimeout(timer);
      resolve({
        status: code,
        stdout,
        stderr
      });
    });
  });
}

