function postJsonNative(urlString, apiKey, bodyObject, timeoutMs = 180000) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const body = JSON.stringify(bodyObject);
    const req = https.request({
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      },
      timeout: timeoutMs
    }, (res) => {
      let raw = '';
      res.on('data', chunk => { raw += chunk.toString(); });
      res.on('end', () => {
        let parsed = raw;
        try { parsed = JSON.parse(raw); } catch (error) {}
        resolve({
          statusCode: Number(res.statusCode || 0),
          headers: res.headers,
          body: parsed,
          raw
        });
      });
    });

    req.on('timeout', () => {
      req.destroy(new Error('Moyin Create Video request timeout'));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

const output = [];

for (const item of items) {
  const j = item.json;
  if (!j.scene_id) throw new Error('Moyin Create Video requires scene_id for per-scene task mapping.');

  const createPath = j.moyin_api?.create?.path || j.moyin_create_path || '/videos';
  const fullUrl = buildMoyinCreateUrl(j.moyin_base_url || $env.MOYIN_API_BASE_URL, createPath);
  const sceneImages = [j.promptImage].filter(Boolean);
  const fallbackImages = (j.image_references || []).map(img => img.raw_url).filter(Boolean);
  const requestBody = {
    model: j.moyin_model || $env.MOYIN_VIDEO_MODEL || 'veo-omni-flash',
    prompt: j.promptText,
    images: sceneImages.length ? sceneImages : fallbackImages,
    aspect_ratio: j.ratio || '9:16',
    aspectRatio: j.ratio || '9:16',
    seconds: String(j.duration || '10')
  };

  let response;
  try {
    response = await postJsonNative(fullUrl, apiKey, requestBody, 180000);
  } catch (error) {
    throw new Error(`Moyin Create Video network error. scene_id=${j.scene_id}; full_url=${fullUrl}; message=${error?.message || String(error)}`);
  }

  const statusCode = Number(response.statusCode || 0);
  const responseBody = response.body;
  const moyinCode = Number(responseBody?.code ?? 0);

  if (statusCode < 200 || statusCode >= 300 || moyinCode >= 400) {
    throw new Error(`Moyin Create Video failed. scene_id=${j.scene_id}; full_url=${fullUrl}; http_status=${statusCode}; request_body=${stringify(requestBody)}; moyin_response=${stringify(responseBody)}`);
  }

  output.push({
    json: {
      ...j,
      moyin_create_scene_id: j.scene_id,
      moyin_create_full_url: fullUrl,
      moyin_create_request_body: requestBody,
      moyin_create_response: responseBody,
      moyin_create_http_status: statusCode
    }
  });
}

return output;

const selected = items.map(item => item.json);
if (!selected.length) return [];
const first = selected[0];
const productId = first.product_id;
const existing = String(first.ai_input?.scripts_history || '').trim();
const lines = existing ? existing.split(/\r?\n/).filter(Boolean) : [];
const records = [];
const createdAt = first.created_at || new Date().toISOString();
for (const ctx of selected) {
  const script = ctx.selected_script;
  const summary = { script_id: script.script_id, product_id: productId, active_skill: ctx.active_skill, angle: script.angle, hook: script.hook, structure_signature: script.structure_signature, scene_order: script.scene_order || [], created_at: createdAt };
  lines.push(JSON.stringify(summary));
  const full = { script_id: script.script_id, product_id: productId, active_skill: ctx.active_skill, skill_path: ctx.skill_path, github_url: ctx.github_url, product_folder: ctx.product_folder, selected_script: script, final_moyin_jobs: script.final_moyin_jobs, created_at: createdAt };
  records.push({ path: `history/products/${productId}/${script.script_id}.json`, content: JSON.stringify(full, null, 2) + '\n', message: `Add script history ${script.script_id}`, sha: null });
}
records.unshift({ path: `history/products/${productId}/index.jsonl`, content: lines.join('\n') + '\n', message: `Update script history index for ${productId}`, sha: first.github_reads?.scripts_history?.sha || null });
return records.map(record => ({ json: { ...first, history_path: record.path, history_content_base64: Buffer.from(record.content, 'utf8').toString('base64'), history_message: record.message, history_sha: record.sha } }));

const token = String($env.GITHUB_TOKEN || '').trim();
if (!token) throw new Error('GITHUB_TOKEN environment variable is required for GitHub history writes.');

const maxRetries = 3;

function encodePath(path) {
  return String(path || '').split('/').map(part => encodeURIComponent(part)).join('/');
}

function decodeBase64(value) {
  return Buffer.from(String(value || ''), 'base64').toString('utf8');
}

function encodeBase64(value) {
  return Buffer.from(String(value || ''), 'utf8').toString('base64');
}

function extractAppendLine(recordContent) {
  const lines = String(recordContent || '').split(/\r?\n/).filter(Boolean);
  return lines.length ? lines[lines.length - 1] : '';
}

function extractScriptIdFromJsonLine(line) {
  try {
    return JSON.parse(line).script_id || '';
  } catch (error) {
    return '';
  }
}

function isShaConflict(statusCode, body) {
  const text = typeof body === 'string' ? body : JSON.stringify(body || {});
  return statusCode === 409 || statusCode === 422 || /sha|expected|is at|conflict/i.test(text);
}

async function githubRequest(method, url, body, ignoreHttpStatusErrors = true) {
  return await this.helpers.httpRequest({
    method,
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'n8n-video-history-writer'
    },
    body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors,
    timeout: 120000
  });
}

async function getCurrentFile(ctx, historyPath) {
  const url = `https://api.github.com/repos/${ctx.owner}/${ctx.repo}/contents/${encodePath(historyPath)}?ref=${encodeURIComponent(ctx.branch)}`;
  const response = await githubRequest.call(this, 'GET', url, undefined, true);
  const statusCode = Number(response.statusCode || 0);

  if (statusCode === 404) {
    return { exists: false, sha: null, content: '' };
  }

  if (statusCode < 200 || statusCode >= 300) {
    const bodyText = typeof response.body === 'string' ? response.body : JSON.stringify(response.body || {});
    throw new Error(`GitHub GET history file failed HTTP ${statusCode}: ${bodyText}`);
  }

  const body = response.body || {};
  const content = body.content ? decodeBase64(String(body.content).replace(/\s/g, '')) : '';
  return { exists: true, sha: body.sha || null, content };
}

async function putFile(ctx, historyPath, content, message, sha) {
  const url = `https://api.github.com/repos/${ctx.owner}/${ctx.repo}/contents/${encodePath(historyPath)}`;
  const body = {
    message,
    content: encodeBase64(content),
    branch: ctx.branch
  };
  if (sha) body.sha = sha;

  return await githubRequest.call(this, 'PUT', url, body, true);
}

function mergeIndexContent(currentContent, appendLine) {
  const currentLines = String(currentContent || '').split(/\r?\n/).filter(Boolean);
  const appendScriptId = extractScriptIdFromJsonLine(appendLine);

  if (appendScriptId) {
    const alreadyExists = currentLines.some(line => extractScriptIdFromJsonLine(line) === appendScriptId);
    if (alreadyExists) return currentLines.join('\n') + (currentLines.length ? '\n' : '');
  }

  if (appendLine) currentLines.push(appendLine);
  return currentLines.join('\n') + (currentLines.length ? '\n' : '');
}

const outputs = [];

for (const item of items) {
  const ctx = item.json;
  const historyPath = ctx.history_path;
  if (!historyPath) throw new Error('history_path is required');

  const originalContent = decodeBase64(ctx.history_content_base64);
  const isIndex = /\/index\.jsonl$/.test(historyPath);
  const appendLine = isIndex ? extractAppendLine(originalContent) : '';

  let lastResponse = null;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const current = await getCurrentFile.call(this, ctx, historyPath);
    const contentToWrite = isIndex
      ? mergeIndexContent(current.content, appendLine)
      : originalContent;

    const response = await putFile.call(this, ctx, historyPath, contentToWrite, ctx.history_message, current.sha);
    lastResponse = response;
    const statusCode = Number(response.statusCode || 0);

    if (statusCode >= 200 && statusCode < 300) {
      outputs.push({
        json: {
          ...ctx,
          github_history_path: historyPath,
          github_history_status: statusCode,
          github_history_sha: response.body?.content?.sha || null,
          github_history_attempts: attempt
        }
      });
      lastResponse = null;
      break;
    }

    if (!isShaConflict(statusCode, response.body) || attempt >= maxRetries) {
      const bodyText = typeof response.body === 'string' ? response.body : JSON.stringify(response.body || {});
      throw new Error(`GitHub PUT history file failed HTTP ${statusCode}: ${bodyText}`);
    }
  }

  if (lastResponse) {
    const bodyText = typeof lastResponse.body === 'string' ? lastResponse.body : JSON.stringify(lastResponse.body || {});
    throw new Error(`GitHub PUT history file failed after retries: ${bodyText}`);
  }
}

return outputs;
